from gurobipy import *

def solve_problem():
    m = Model("Battlefield_Logistics")
    m.setParam("TimeLimit", 100)  # Set time limit to 100 seconds

    # Data
    depots = list(range(9))  # D0..D8
    units = list(range(10))  # U0..U9
    supplies = list(range(2))  # S0..S1
    days = list(range(1))  # Day0..Day0

    demands = [[[46.51], [19.58]], [[42.75], [10.31]], [[23.63], [21.94]], [[33.6], [37.09]], [[15.13], [45.4]], [[25.2], [27.4]], [[23.39], [49.42]], [[26.14], [42.26]], [[12.2], [25.33]], [[12.19], [37.99]]]
    depot_supplies = [[[34.8], [37.1]], [[24.46], [51.67]], [[32.73], [46.77]], [[39.19], [52.28]], [[23.55], [37.04]], [[35.09], [48.31]], [[37.36], [43.76]], [[36.74], [42.93]], [[36.46], [30.89]]]
    transport_costs = [[3.96, 3.1, 2.3, 3.17, 4.42, 4.11, 4.2, 2.27, 2.47, 4.5], [3.69, 3.28, 4.65, 4.08, 4.43, 2.89, 1.87, 2.03, 4.53, 1.21], [4.4, 3.07, 2.41, 1.78, 2.65, 1.62, 4.71, 4.15, 1.75, 4.27], [1.71, 2.44, 3.39, 4.79, 4.82, 3.2, 1.01, 3.4, 3.56, 4.61], [2.01, 3.37, 4.66, 4.47, 4.21, 4.33, 4.85, 1.46, 1.3, 2.54], [3.8, 4.53, 4.13, 2.14, 4.87, 4.0, 1.96, 1.66, 4.13, 4.72], [3.49, 2.61, 1.74, 3.0, 4.96, 1.45, 2.03, 3.3, 2.08, 2.36], [2.12, 1.2, 4.29, 2.09, 2.44, 1.97, 3.8, 2.22, 1.7, 4.59], [1.31, 4.04, 3.82, 1.75, 3.89, 4.78, 3.66, 3.78, 3.97, 3.91]]
    risk_costs = [[143.66, 168.15, 177.55, 166.29, 197.53, 116.88, 116.78, 64.51, 110.64, 158.28], [180.45, 162.64, 55.58, 73.99, 144.63, 85.64, 179.65, 71.72, 127.06, 67.22], [186.86, 83.1, 177.3, 57.14, 109.9, 169.59, 93.27, 169.16, 82.35, 166.97], [147.02, 66.45, 156.9, 72.77, 68.57, 108.82, 133.54, 66.09, 127.19, 137.46], [126.55, 160.62, 149.1, 76.27, 61.92, 195.36, 196.6, 96.43, 169.75, 65.83], [179.03, 144.58, 61.45, 51.58, 108.41, 168.59, 186.15, 102.04, 118.29, 174.14], [165.81, 80.17, 104.42, 62.44, 183.79, 190.32, 75.81, 77.0, 83.89, 176.1], [125.49, 108.68, 151.16, 94.85, 59.9, 184.0, 75.2, 73.17, 53.57, 71.98], [110.05, 176.24, 113.76, 172.58, 157.91, 170.48, 55.82, 163.56, 80.5, 57.04]]
    supply_volumes = [0.89, 1.0]
    penalty_costs = [56.73, 82.51]
    vehicle_cost = 10.0
    vehicle_capacity = 89.0
    total_vehicles = 23

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
